UPDATE harvest_run SET state = #{state}, calls = #{calls}, works_seen = #{seen}, works_new = #{created},
  error = #{error}, finished = now()
WHERE id = #{id}

UPDATE harvest_run SET state = #{state}, error = COALESCE(#{error}, error),
  finished = CASE WHEN #{state}::text IN ('DONE','FAILED') THEN now() ELSE NULL END
WHERE id = #{id}
